begin;
do $$
declare actor uuid:='9f44daf9-9f87-4129-bc71-55c082cf8782';org uuid;org2 uuid;b uuid;b2 uuid;outlet uuid;c uuid;req uuid:=gen_random_uuid();result jsonb;again jsonb;payload jsonb;denied boolean;real_maps integer;before_connections integer;before_members integer;
begin
 select count(*) into real_maps from public.brand_outlets;select count(*) into before_connections from public.marketing_connections;select count(*) into before_members from public.organization_memberships;
 perform set_config('request.jwt.claim.sub',(select auth_user_id::text from public.employees where id=actor),true);
 org:=(public.platform_organization_command('create_organization',null,'{"name":"QA disposable Brand mapping scope"}')->>'organization_id')::uuid;
 org2:=(public.platform_organization_command('create_organization',null,'{"name":"QA disposable other organization"}')->>'organization_id')::uuid;
 insert into public.outlets(name,code,is_active,status) values('QA disposable mapping outlet','QABND',true,'active') returning id into outlet;
 result:=public.platform_organization_command('save_brand',org,'{"name":"QA disposable brand","timezone":"Asia/Kuala_Lumpur","outlet_ids":[]}');b:=(result->>'brand_id')::uuid;
 assert (select count(*) from public.brand_outlets where brand_id=b)=0;
 denied:=false;begin perform public.platform_organization_command('save_brand',org,jsonb_build_object('id',b,'expected_revision',1,'name','QA disposable brand','outlet_ids',jsonb_build_array(outlet)));exception when others then denied:=true;end;assert denied;
 payload:=jsonb_build_object('id',b,'expected_revision',1,'name','QA disposable brand','timezone','Asia/Kuala_Lumpur','outlet_ids',jsonb_build_array(outlet),'mapping_confirmed',true,'request_id',req);
 result:=public.platform_organization_command('save_brand',org,payload);again:=public.platform_organization_command('save_brand',org,payload);assert result=again;
 assert (select organization_id from public.organization_outlets where outlet_id=outlet)=org;
 denied:=false;begin perform public.platform_organization_command('save_brand',org,payload||jsonb_build_object('request_id',gen_random_uuid()));exception when serialization_failure then denied:=true;end;assert denied;
 result:=public.platform_organization_command('save_brand',org,jsonb_build_object('name','QA second brand','outlet_ids',jsonb_build_array(outlet),'mapping_confirmed',true));b2:=(result->>'brand_id')::uuid;
 assert (select count(*) from public.brand_outlets where outlet_id=outlet)=2;
 denied:=false;begin perform public.platform_organization_command('save_brand',org2,jsonb_build_object('name','QA forbidden organization mapping','outlet_ids',jsonb_build_array(outlet),'mapping_confirmed',true));exception when insufficient_privilege then denied:=true;end;assert denied;
 denied:=false;begin perform public.platform_organization_command('save_brand',org,'{"name":"qa DISPOSABLE brand","outlet_ids":[]}');exception when unique_violation then denied:=true;end;assert denied;
 insert into public.marketing_content(organization_id,brand_id,status,scheduled_at,created_by) values(org,b,'scheduled',now()+interval '1 day',actor) returning id into c;
 result:=public.platform_organization_command('set_brand_status',org,jsonb_build_object('id',b,'expected_revision',2,'is_active',false,'confirmed',true));
 assert (select status from public.marketing_content where id=c)='scheduled';
 assert marketing_private.brand_allowed(org,b);
 assert exists(select 1 from jsonb_array_elements(public.marketing_context()->'brands') item where item->>'id'=b::text and (item->>'is_active')::boolean=false);
 denied:=false;begin insert into public.marketing_content(organization_id,brand_id,created_by) values(org,b,actor);exception when others then denied:=true;end;assert denied;
 update public.marketing_content set status='published' where id=c;assert (select status from public.marketing_content where id=c)='published';
 result:=public.platform_organization_command('set_brand_status',org,jsonb_build_object('id',b,'expected_revision',3,'is_active',true,'confirmed',true));
 result:=public.platform_organization_command('save_brand',org,jsonb_build_object('id',b,'expected_revision',4,'name','QA renamed brand','timezone','Asia/Singapore','outlet_ids','[]'::jsonb,'mapping_confirmed',true));
 assert (select count(*) from public.brand_outlets where brand_id=b)=0 and (select count(*) from public.brand_outlets where brand_id=b2)=1;
 assert exists(select 1 from public.marketing_events where brand_id=b and details->'before'->>'name'='QA disposable brand' and details->'after'->>'name'='QA renamed brand');
 assert not has_table_privilege('authenticated','public.brands','UPDATE');assert not has_function_privilege('anon','public.platform_brands_read(uuid)','EXECUTE');
 delete from public.organization_memberships where organization_id=org and employee_id=actor;
 denied:=false;begin perform public.platform_organization_command('save_brand',org,payload);exception when insufficient_privilege then denied:=true;end;assert denied;
 assert (select count(*) from public.marketing_connections)=before_connections;
 assert (select count(*) from public.brand_outlets where brand_id in ('88718f61-2915-42ef-b62f-5e6e2fe5b3eb','88a73473-5dc7-471c-b484-fe247cf0f660','0aa8ac72-6c63-4eb5-a024-1e942e6dbe4e'))=real_maps;
end;$$;
select 'PASS: optional outlets, reviewed mapping, retry/CAS, same-organization many-to-many, cross-organization rejection, normalized duplicates, inactive/history/schedule preservation, reactivation, unlink audit, revoked membership and protected grants; disposable records rolled back' as verification;
rollback;
